#pragma once
#include <cerrno>
#include <fstream>
#include <string>
#include <unistd.h>
namespace android::base {
inline bool ReadFully(int fd,void* p,size_t n){size_t off=0;while(off<n){ssize_t r=read(fd,(char*)p+off,n-off);if(r<0&&errno==EINTR)continue;if(r<=0)return false;off+=r;}return true;}
inline bool WriteFully(int fd,const void* p,size_t n){size_t off=0;while(off<n){ssize_t r=write(fd,(const char*)p+off,n-off);if(r<0&&errno==EINTR)continue;if(r<=0)return false;off+=r;}return true;}
inline bool ReadFileToString(const std::string& p,std::string* s){std::ifstream f(p);if(!f)return false;*s=std::string(std::istreambuf_iterator<char>(f),{});return !f.bad();}
}

